#!/usr/bin/env python3
"""Convert itwinjs-core's recorded imdl tile fixtures to a C++ header.

Source: itwinjs-core full-stack-tests/core/src/frontend/standalone/tile/data/
        TileIO.data.{1.1,1.2,1.3,1.4,2.0}.ts — binary tile data recorded from
        the real backend for 5 geometry scenarios per format version.
Output: TileIOFixtures.h — one byte array + metadata per (version, scenario).

Run from anywhere; paths are resolved relative to the sibling layout:
  ../itwinjs-core/... (reference repo) → ./TileIOFixtures.h
"""

import re
from pathlib import Path

HERE = Path(__file__).resolve().parent
SRC = Path("D:/Github/itwinjs-core/full-stack-tests/core/src/frontend/standalone/tile/data")
VERSIONS = ["1.1", "1.2", "1.3", "1.4", "2.0"]
SCENARIOS = ["rectangle", "lineString", "lineStrings", "triangles", "cylinder"]

def parse_ts(path):
    text = path.read_text(encoding="utf-8")
    meta = {}
    meta["versionMajor"] = int(re.search(r"versionMajor:\s*(\d+)", text).group(1))
    meta["versionMinor"] = int(re.search(r"versionMinor:\s*(\d+)", text).group(1))
    meta["headerLength"] = int(re.search(r"headerLength:\s*(\d+)", text).group(1))
    scenarios = {}
    for sc in SCENARIOS:
        m = re.search(
            rf"{sc}:\s*\{{\s*flags:\s*([A-Za-z0-9.| ]+?),\s*bytes:\s*new Uint8Array\(\[(.*?)\]\)",
            text, re.S)
        if not m:
            continue
        flags = m.group(1).strip().rstrip(",")
        body = m.group(2)
        # Handle both `0x..` hex and decimal entries; stop at the closing of array.
        entries = re.findall(r"0x[0-9a-fA-F]+|\d+", body)
        # The regex may overrun into following numbers outside the array; the
        # body group is bounded by `\]` so entries are exact.
        scenarios[sc] = {
            "flags": flags,
            "bytes": bytes(int(e, 0) for e in entries),
        }
    return meta, scenarios


def cpp_name(ver):
    return "V" + ver.replace(".", "_")


def main():
    out = []
    out.append("// SPDX-License-Identifier: MIT")
    out.append("// DanQing imdl test fixtures — recorded backend tile data.")
    out.append("// Ported from: itwinjs-core full-stack-tests/core/src/frontend/")
    out.append("//              standalone/tile/data/TileIO.data.{1.1..2.0}.ts")
    out.append("// Generated by convert_fixtures.py — do not edit by hand.")
    out.append("#pragma once")
    out.append("#include <cstdint>")
    out.append("#include <cstddef>")
    out.append("namespace dqRender { namespace fixtures {")
    for ver in VERSIONS:
        meta, scenarios = parse_ts(SRC / f"TileIO.data.{ver}.ts")
        assert len(scenarios) == 5, (ver, scenarios.keys())
        cap = cpp_name(ver)
        out.append(f"struct {cap} {{")
        out.append(f"  static constexpr unsigned versionMajor = {meta['versionMajor']};")
        out.append(f"  static constexpr unsigned versionMinor = {meta['versionMinor']};")
        out.append(f"  static constexpr unsigned headerLength = {meta['headerLength']};")
        for sc, data in scenarios.items():
            arr = ", ".join(f"0x{b:02x}" for b in data["bytes"])
            out.append(f"  static uint8_t const {sc}Bytes[];")
            out.append(f"  static size_t const {sc}Size = {len(data['bytes'])};")
        out.append("};")
    out.append("")
    for ver in VERSIONS:
        _, scenarios = parse_ts(SRC / f"TileIO.data.{ver}.ts")
        cap = cpp_name(ver)
        for sc, data in scenarios.items():
            arr = ", ".join(f"0x{b:02x}" for b in data["bytes"])
            out.append(f"uint8_t const {cap}::{sc}Bytes[] = {{ {arr} }};")
    out.append("}}  // namespace fixtures, dqRender")
    (HERE / "TileIOFixtures.h").write_text("\n".join(out), encoding="utf-8", newline="\n")
    print("TileIOFixtures.h written")


if __name__ == "__main__":
    main()
